const item = $input.first().json;
const body = item.body || item;

const base64 = body.audio_base64;
const buffer = Buffer.from(base64, 'base64');

const phoneRaw = String(body.phone || '');
const phoneDigits = phoneRaw.replace(/[^0-9]/g, '');

let country = 'unknown';

if (phoneDigits.startsWith('91')) {
  country = 'india';
}
else if (phoneDigits.startsWith('977')) {
  country = 'nepal';
}
else if (phoneDigits.startsWith('58')) {
  country = 'venezuela';
}
else if (phoneDigits.startsWith('52')) {
  country = 'mexico';
}
else if (phoneDigits.startsWith('57')) {
  country = 'colombia';
}

return [{
  json: {
    phone: body.phone,
    date: body.date,
    filename: body.filename,
    country: country
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'audio/wav',
      fileName: body.filename
    }
  }
}];

