// Trae grabaciones Stringee >1min (últimas 24h) y convierte a base64
const now_seconds = Math.floor(Date.now() / 1000);
const from_seconds = now_seconds - 86400;

const callLogUrl = `http://172.18.0.1:8091/call-log?limit=500&from_start_time=${from_seconds}`;

try {
  const callLogResp = await fetch(callLogUrl);
  const callLogData = await callLogResp.json();
  const calls = callLogData.data?.calls || [];

  const validCalls = calls.filter(c => Number(c.answer_duration || 0) >= 60);

  console.log(`Stringee: ${calls.length} total, ${validCalls.length} con >1min`);

  const results = [];

  for (const call of validCalls) {
    try {
      const callId = call.id;
      const toNumber = call.to_number;
      const duration = call.answer_duration;
      const startTime = new Date(call.start_time).toISOString().split('T')[0];

      let country = 'unknown';
      const digits = String(toNumber).replace(/[^0-9]/g, '');
      if (digits.startsWith('91')) country = 'india';
      else if (digits.startsWith('977')) country = 'nepal';
      else if (digits.startsWith('52')) country = 'mexico';
      else if (digits.startsWith('57')) country = 'colombia';
      else if (digits.startsWith('58')) country = 'venezuela';

      const recordingUrl = `http://172.18.0.1:8091/call-recording/${callId}`;
      const recordResp = await fetch(recordingUrl);
      const recordData = await recordResp.json();

      if (recordData.ok && recordData.audio_base64) {
        results.push({
          json: {
            phone: toNumber,
            date: startTime,
            filename: `stringee-${callId}-${duration}s.wav`,
            country: country,
            duration: duration,
            call_id: callId
          },
          binary: {
            data: {
              data: recordData.audio_base64,
              mimeType: 'audio/wav',
              fileName: `stringee-${callId}-${duration}s.wav`
            }
          }
        });
        console.log(`OK ${toNumber} (${country}) - ${duration}s`);
      } else {
        console.log(`SKIP ${toNumber} - no recording data`);
      }
    } catch (e) {
      console.log(`ERROR descargando ${call.id}: ${e.message}`);
    }
  }

  return results;
} catch (e) {
  console.error(`Error GET call-log: ${e.message}`);
  return [];
}

