// Trae audio de ElevenLabs para cada conversation_id vinculado a Stringee
const rows = $input.all().map(i => i.json);
const results = [];

for (const row of rows) {
  try {
    const convId = row.conversation_id;
    const toNumber = row.phone;
    const duration = row.duration_secs;
    const startTime = new Date(Number(row.start_time)).toISOString().split('T')[0];

    let country = 'unknown';
    const digits = String(toNumber).replace(/[^0-9]/g, '');
    if (digits.startsWith('91')) country = 'india';
