    const audioUrl = `http://172.18.0.1:8091/call-audio/${convId}`;
    const audioResp = await fetch(audioUrl);
    const audioData = await audioResp.json();

    if (audioData.ok && audioData.audio_base64) {
      results.push({
        json: {
          phone: toNumber,
          date: startTime,
          filename: `stringee-${convId}-${duration}s.mp3`,
          country: country,
          duration: duration,
          conversation_id: convId,
          call_id: row.call_id
        },
        binary: {
          data: {
            data: audioData.audio_base64,
            mimeType: 'audio/mpeg',
            fileName: `stringee-${convId}-${duration}s.mp3`
          }
        }
      });
      console.log(`OK ${toNumber} (${country}) - ${duration}s - conv:${convId}`);
    } else {
      console.log(`SKIP ${toNumber} - audio no disponible: ${JSON.stringify(audioData)}`);
    }
  } catch (e) {
    console.log(`ERROR ${row.conversation_id}: ${e.message}`);
  }
}

return results;

