// Lee grabaciones locales del worker Stringee (bridge-call.js las graba en vivo)
const listData = await this.helpers.httpRequest({
  method: 'GET',
  url: 'http://172.18.0.1:8091/recordings',
  json: true
});
const files = listData.recordings || [];

const results = [];

for (const rec of files) {
  try {
    const dlData = await this.helpers.httpRequest({
      method: 'GET',
      url: `http://172.18.0.1:8091/recordings/${rec.filename}`,
      json: true
    });

    if (!dlData.ok || !dlData.audio_base64) {
      console.log(`SKIP ${rec.filename} - no se pudo descargar`);
      continue;
    }

    const digits = String(rec.phone).replace(/[^0-9]/g, '');
    let country = 'unknown';
    if (digits.startsWith('91')) country = 'india';
    else if (digits.startsWith('977')) country = 'nepal';

    const date = new Date(rec.timestamp_ms).toISOString().split('T')[0];

    results.push({
      json: {
        phone: rec.phone,
        date: date,
        filename: rec.filename,
        country: country,
        size_bytes: rec.size_bytes
      },
      binary: {
        data: {
          data: dlData.audio_base64,
          mimeType: 'audio/wav',
          fileName: rec.filename
        }
      }
    });
    console.log(`OK ${rec.phone} (${country}) - ${rec.filename}`);
  } catch (e) {
    console.log(`ERROR ${rec.filename}: ${e.message}`);
  }
}

return results;

